INSERT INTO Leader_Flavors SELECT 'LEADER_GPT_SOL',Type,CASE Type WHEN 'FLAVOR_SCIENCE' THEN 10 WHEN 'FLAVOR_GROWTH' THEN 8 WHEN 'FLAVOR_GREAT_PEOPLE' THEN 9 WHEN 'FLAVOR_WONDER' THEN 8 WHEN 'FLAVOR_PRODUCTION' THEN 6 WHEN 'FLAVOR_DEFENSE' THEN 7 WHEN 'FLAVOR_CITY_DEFENSE' THEN 7 WHEN 'FLAVOR_OFFENSE' THEN 4 WHEN 'FLAVOR_EXPANSION' THEN 4 WHEN 'FLAVOR_GOLD' THEN 5 WHEN 'FLAVOR_CULTURE' THEN 7 WHEN 'FLAVOR_RELIGION' THEN 4 WHEN 'FLAVOR_DIPLOMACY' THEN 5 WHEN 'FLAVOR_HAPPINESS' THEN 7 WHEN 'FLAVOR_TILE_IMPROVEMENT' THEN 7 ELSE 5 END FROM Flavors;
INSERT INTO Leader_MajorCivApproachBiases SELECT 'LEADER_GPT_SOL',MajorCivApproachType,CASE WHEN MajorCivApproachType LIKE '%WAR' THEN 2 WHEN MajorCivApproachType LIKE '%FRIENDLY' THEN 7 ELSE 5 END FROM Leader_MajorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
INSERT INTO Leader_MinorCivApproachBiases SELECT 'LEADER_GPT_SOL',MinorCivApproachType,CASE WHEN MinorCivApproachType LIKE '%WAR' THEN 2 WHEN MinorCivApproachType LIKE '%FRIENDLY' THEN 7 ELSE 5 END FROM Leader_MinorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
